/**
 * The forecast line in the status bar, beside the word count.
 *
 *   on pace for ~900 today (700–1,100) · done ~Nov 14 (Nov 8 – 25)
 *
 * It also keeps the pace ledger: every saved draft's word count is folded
 * into `writing-pace-ledger`, so the history exists whether or not the line
 * is showing. The line itself steps aside in Zen and whenever the flow
 * reading says a run is building — a pace figure is the last thing a writer
 * in flow needs to see — and comes back at the next pause.
 */
import { component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import type { DraftContentDetail } from "../../types";
import {
  FLOW_EVENT,
  flowSnapshot,
  type FlowSnapshot,
} from "./extensions/flow-conductor";
import {
  hasAuthenticatedConvexIdentity,
  useAuth,
} from "../../utils/auth-context";
import { useConvexClient } from "../../utils/convex-context";
import { dailyCreditRunway } from "../../utils/credit-runway";
import { loadBriefFromIdb } from "../../utils/idb";
import {
  briefWordTarget,
  clientAsk,
  creditNeedsNotice,
  FORECAST_PREVIEW_EVENT,
  finishForecast,
  formatDay,
  formatDayRange,
  formatWordRange,
  formatWords,
  paceForecast,
  type CreditForecast,
  type FinishForecast,
  type PaceForecast,
} from "../../utils/writing-forecasts";
import {
  loadPaceLedger,
  recordWordCount,
} from "../../utils/writing-pace-ledger";


const REFRESH_MS = 5 * 60_000;
const RECORD_MS = 20_000;

interface LineState {
  pace: PaceForecast | null;
  finish: FinishForecast | null;
  credit: CreditForecast | null;
  quiet: boolean;
}

export const ForecastLine = component$<{
  folioId: string | null;
  wordCount: number;
  zen: boolean;
}>((props) => {
  const auth = useAuth();
  const clientSignal = useConvexClient();
  const state = useStore<LineState>({
    pace: null,
    finish: null,
    credit: null,
    quiet: false,
  });

  // Mobile hides this span; "document-ready" so the ledger still records.
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(
    ({ track, cleanup }) => {
      const folioId = track(() => props.folioId);
      track(() => auth.value.user?.analyticsId);
      const client = track(() => clientSignal.value);
      let disposed = false;
      let preview = false;
      let pending: { folioId: string; words: number } | null = null;
      let lastRecord = 0;

      const refresh = async () => {
        if (disposed || preview) return;
        const now = Date.now();
        const ledger = await loadPaceLedger();
        const ask = clientAsk(client);
        const [pace, finish] = await Promise.all([
          paceForecast(ledger, now, { ask }).catch(() => null),
          folioId
            ? loadBriefFromIdb(folioId)
                .then((brief) =>
                  finishForecast({
                    ledger,
                    folioId,
                    currentWords: props.wordCount,
                    target: briefWordTarget(brief),
                    now,
                    options: { ask },
                  }),
                )
                .catch(() => null)
            : null,
        ]);
        if (disposed || preview) return;
        state.pace = pace;
        state.finish = finish;
      };

      const loadCredit = async () => {
        const accountId = auth.value.user?.analyticsId;
        if (!client || !accountId || !hasAuthenticatedConvexIdentity(auth.value))
          return;
        const credit = await dailyCreditRunway(client, accountId).catch(
          () => null,
        );
        if (!disposed && !preview) state.credit = credit;
      };

      const onContent = (event: Event) => {
        const detail = (event as CustomEvent<DraftContentDetail>).detail;
        if (!folioId || typeof detail?.wordCount !== "number") return;
        pending = { folioId, words: detail.wordCount };
      };
      // Count only what reached the disk, for the draft that was saved.
      const onSaved = (event: Event) => {
        const saved = (event as CustomEvent<{ folioId?: string }>).detail
          ?.folioId;
        if (!pending || pending.folioId !== saved) return;
        const now = Date.now();
        if (now - lastRecord < RECORD_MS) return;
        lastRecord = now;
        const { folioId: id, words } = pending;
        pending = null;
        void recordWordCount(id, words, now)
          .then(refresh)
          .catch(() => undefined);
      };
      const onFlow = (snap: FlowSnapshot) => {
        state.quiet =
          snap.enabled && (snap.mode === "flow" || snap.mode === "settling");
      };
      const onFlowEvent = (event: Event) =>
        onFlow((event as CustomEvent<FlowSnapshot>).detail);
      const onPreview = (event: Event) => {
        const detail = (event as CustomEvent<Partial<LineState>>).detail ?? {};
        preview = true;
        state.pace = detail.pace ?? null;
        state.finish = detail.finish ?? null;
        state.credit = detail.credit ?? null;
      };

      onFlow(flowSnapshot());
      window.addEventListener("twyne:content", onContent);
      window.addEventListener("twyne:draft-saved", onSaved);
      window.addEventListener(FLOW_EVENT, onFlowEvent);
      if (import.meta.env.DEV)
        window.addEventListener(FORECAST_PREVIEW_EVENT, onPreview);
      void refresh();
      void loadCredit();
      const timer = window.setInterval(() => void refresh(), REFRESH_MS);
      cleanup(() => {
        disposed = true;
        window.clearInterval(timer);
        window.removeEventListener("twyne:content", onContent);
        window.removeEventListener("twyne:draft-saved", onSaved);
        window.removeEventListener(FLOW_EVENT, onFlowEvent);
        window.removeEventListener(FORECAST_PREVIEW_EVENT, onPreview);
      });
    },
    { strategy: "document-ready" },
  );

  const credit = creditNeedsNotice(state.credit, Date.now())
    ? state.credit
    : null;
  // One stable root: swapping it would restart the task above.
  const hidden =
    props.zen || state.quiet || (!state.pace && !state.finish && !credit);

  const paceText = state.pace
    ? `On pace for ~${formatWords(state.pace.median)} words today (${formatWordRange(state.pace)}); ${formatWords(state.pace.wordsSoFar)} so far.`
    : "";
  const finishText = state.finish
    ? `Draft reaches ${formatWords(state.finish.target)} words around ${formatDay(state.finish.median)} (${formatDayRange(state.finish.early, state.finish.late)}).`
    : "";

  return (
    <span class="editor-forecast" data-testid="forecast-line" hidden={hidden}>
      {!hidden && state.pace && (
        <span class="editor-forecast__item" title={paceText}>
          on pace for ~{formatWords(state.pace.median)} today
          {formatWordRange(state.pace).includes("–") && (
            <span class="editor-forecast__range">
              {" "}({formatWordRange(state.pace)})
            </span>
          )}
        </span>
      )}
      {!hidden && state.finish && (
        <span class="editor-forecast__item" title={finishText}>
          done ~{formatDay(state.finish.median)}
          {state.finish.early !== state.finish.late && (
            <span class="editor-forecast__range">
              {" "}({formatDayRange(state.finish.early, state.finish.late)})
            </span>
          )}
        </span>
      )}
      {!hidden && credit?.runsOut && (
        <Link
          href="/desk/"
          class="editor-forecast__item editor-forecast__credit"
          title={`Hosted credit runs out around ${formatDay(credit.runsOut.median)} (${formatDayRange(credit.runsOut.early, credit.runsOut.late)}) at your recent pace. Open the desk.`}
        >
          credit to ~{formatDay(credit.runsOut.median)}
        </Link>
      )}
    </span>
  );
});

/**
 * The deterministic half of every forecast Twyne shows.
 *
 * Clairic's forecasts drift toward the average, and with a week of history
 * there is no average worth drifting toward. So each surface is computed here
 * first, from the writer's own numbers, and the model is only allowed to
 * replace it when there is enough history and it lands near this answer
 * (`preferForecast`). Everything is an 80% interval: median, p10, p90.
 */
import type { Interval } from "./extraction";

/** z for the 10th/90th percentile of a normal. */
const Z80 = 1.2816;

export function quantile(values: readonly number[], q: number): number {
  if (!values.length) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const index = Math.min(sorted.length - 1, Math.max(0, (sorted.length - 1) * q));
  const lo = Math.floor(index);
  const hi = Math.ceil(index);
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (index - lo);
}

export function meanAndSd(values: readonly number[]): { mean: number; sd: number } {
  if (!values.length) return { mean: 0, sd: 0 };
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  if (values.length < 2) return { mean, sd: 0 };
  const variance =
    values.reduce((sum, v) => sum + (v - mean) ** 2, 0) / (values.length - 1);
  return { mean, sd: Math.sqrt(variance) };
}

/* ── Today's pace ─────────────────────────────────────────────── */

export interface PaceHistoryDay {
  /** 0 = Sunday, as `Date#getDay`. */
  weekday: number;
  /** Net words per local hour. */
  hours: number[];
}

export const PACE_MIN_DAYS = 3;

/**
 * Words the writer will finish today with, from what they usually add after
 * this point in the day.
 *
 * Conditioned on writing days only: the line only shows once today has
 * begun, so the question is "on days like this, how much more came?". Uses
 * the same weekday when there are three of them, every writing day
 * otherwise. The interval is the empirical spread of those days' remainders.
 */
export function paceBaseline(input: {
  history: readonly PaceHistoryDay[];
  weekday: number;
  /** Fractional local hour now, e.g. 14.5 at half past two. */
  hourNow: number;
  wordsSoFar: number;
}): (Interval & { days: number }) | null {
  const writing = input.history.filter((d) =>
    d.hours.some((n) => n > 0),
  );
  if (writing.length < PACE_MIN_DAYS) return null;
  const sameDay = writing.filter((d) => d.weekday === input.weekday);
  const pool = sameDay.length >= PACE_MIN_DAYS ? sameDay : writing;
  const hour = Math.min(23, Math.max(0, Math.floor(input.hourNow)));
  const left = 1 - (input.hourNow - hour);
  const remainders = pool.map((d) => {
    let rest = Math.max(0, d.hours[hour] ?? 0) * left;
    for (let h = hour + 1; h < 24; h++) rest += Math.max(0, d.hours[h] ?? 0);
    return rest;
  });
  const base = Math.max(0, input.wordsSoFar);
  return {
    median: base + quantile(remainders, 0.5),
    p10: base + quantile(remainders, 0.1),
    p90: base + quantile(remainders, 0.9),
    days: pool.length,
  };
}

/* ── Reaching a total: draft length, or spending a balance ───────── */

/**
 * Days until a running sum of daily increments reaches `remaining`, as an
 * interval. Treats days as independent draws with the observed mean and
 * spread, so after `d` days the sum is ~N(d·m, d·s²); solving
 * d·m ± z·s·√d = remaining for √d gives the early and late crossings.
 * Null when the pace is not moving toward the total at all.
 */
export function daysToReach(
  dailyIncrements: readonly number[],
  remaining: number,
  minDays = PACE_MIN_DAYS,
): Interval | null {
  if (remaining <= 0) return { median: 0, p10: 0, p90: 0 };
  if (dailyIncrements.length < minDays) return null;
  const { mean, sd } = meanAndSd(dailyIncrements);
  if (mean <= 0) return null;
  const root = (sign: 1 | -1) => {
    const b = sign * Z80 * sd;
    const x = (-b + Math.sqrt(b * b + 4 * mean * remaining)) / (2 * mean);
    return x * x;
  };
  return {
    median: remaining / mean,
    p10: root(1),
    p90: root(-1),
  };
}

/* ── This month's hosted spend ─────────────────────────────────── */

export interface DailyAmount {
  weekday: number;
  amount: number;
}

/**
 * Total for a period given what is already spent and the days still to
 * come. Weekday-aware once each weekday has been seen three times (writers
 * often have a heavy day); a flat trailing mean before that. The interval
 * comes from the residuals of that model, widened by √days.
 */
export function periodTotalBaseline(input: {
  history: readonly DailyAmount[];
  spentSoFar: number;
  /** Weekdays of the days left in the period, today's remainder excluded. */
  upcoming: readonly number[];
}): Interval | null {
  if (input.history.length < PACE_MIN_DAYS) return null;
  const byWeekday = new Map<number, number[]>();
  for (const d of input.history)
    byWeekday.set(d.weekday, [...(byWeekday.get(d.weekday) ?? []), d.amount]);
  const weekdayAware = [...Array(7).keys()].every(
    (w) => (byWeekday.get(w)?.length ?? 0) >= 3,
  );
  const overall = meanAndSd(input.history.map((d) => d.amount)).mean;
  const expected = (weekday: number) =>
    weekdayAware ? meanAndSd(byWeekday.get(weekday)!).mean : overall;
  const residuals = input.history.map((d) => d.amount - expected(d.weekday));
  const sd = meanAndSd(residuals).sd;
  const ahead = input.upcoming.reduce((sum, w) => sum + expected(w), 0);
  const spread = Z80 * sd * Math.sqrt(input.upcoming.length);
  const median = input.spentSoFar + ahead;
  return {
    median,
    p10: Math.max(input.spentSoFar, median - spread),
    p90: median + spread,
  };
}

/* ── Model vs baseline ──────────────────────────────────────────── */

/**
 * Take the model's interval only when history is long enough to trust it
 * and its median sits within the baseline's band widened by half its width
 * on each side (never less than 15% of the baseline median, so a perfectly
 * steady record does not shut the model out entirely). Otherwise the baseline stands: a model answer far from the
 * writer's own record is the drift-to-average failure, not insight.
 */
export function preferForecast(
  baseline: Interval | null,
  model: Interval | null,
  enoughHistory: boolean,
): { value: Interval; source: "baseline" | "clairic" } | null {
  if (!baseline) return null;
  if (!model || !enoughHistory) return { value: baseline, source: "baseline" };
  const half = Math.max(
    (baseline.p90 - baseline.p10) / 2,
    Math.abs(baseline.median) * 0.15,
    1e-9,
  );
  const ok =
    model.median >= baseline.p10 - half &&
    model.median <= baseline.p90 + half &&
    model.p10 <= model.median &&
    model.median <= model.p90;
  return ok
    ? { value: model, source: "clairic" }
    : { value: baseline, source: "baseline" };
}

/**
 * Steps of a per-day (or per-hour) forecast, summed until they cover
 * `remaining`. Returns the 1-based step index where the median, the fast
 * edge (p90 increments) and the slow edge (p10 increments) cross, or null
 * when the median never crosses inside the horizon. A slow edge that never
 * crosses is reported at the horizon's end + 1 so the caller can see it.
 */
export function stepsToReach(
  steps: readonly Interval[],
  remaining: number,
): Interval | null {
  if (remaining <= 0) return { median: 0, p10: 0, p90: 0 };
  const cross = (pick: (s: Interval) => number) => {
    let sum = 0;
    for (let i = 0; i < steps.length; i++) {
      sum += Math.max(0, pick(steps[i]));
      if (sum >= remaining) return i + 1;
    }
    return null;
  };
  const median = cross((s) => s.median);
  if (median === null) return null;
  return {
    median,
    p10: cross((s) => s.p90) ?? median,
    p90: cross((s) => s.p10) ?? steps.length + 1,
  };
}

/** Sum of step intervals: a loose but honest bound on a total. */
export function sumSteps(steps: readonly Interval[]): Interval {
  return steps.reduce(
    (acc, s) => ({
      median: acc.median + s.median,
      p10: acc.p10 + s.p10,
      p90: acc.p90 + s.p90,
    }),
    { median: 0, p10: 0, p90: 0 },
  );
}
/**
 * The three forecasts the writer sees — today's pace, when the draft is
 * done, and how long hosted credit lasts — each a baseline from
 * `forecast-baselines`, optionally replaced by one Clairic forecast a day.
 *
 * Nothing here renders. Callers get a median and an 80% interval, or null
 * when there is nothing honest to say yet.
 */
import type { ConvexClient } from "convex/browser";
import type { ProjectBrief } from "../types";
import {
  forecast,
  forecastSteps,
  type ExtractionRequest,
  type ExtractionResult,
  type Interval,
} from "./extraction";
import { askExtraction } from "./extraction-client";
import {
  daysToReach,
  paceBaseline,
  periodTotalBaseline,
  preferForecast,
  stepsToReach,
  sumSteps,
  type DailyAmount,
  type PaceHistoryDay,
} from "./forecast-baselines";
import { dailyForecast, type ForecastCacheStore } from "./forecast-cache";
import {
  addDays,
  dayToTime,
  dayTotal,
  folioDailyGains,
  localDay,
  type PaceLedger,
} from "./writing-pace-ledger";

/** Days of history before Clairic is asked at all. */
export const MODEL_MIN_DAYS = 14;
/** Below this many words today, a pace line is noise. */
export const PACE_MIN_WORDS_TODAY = 50;
const HISTORY_DAYS = 28;
const FINISH_HORIZON_DAYS = 60;
const CREDIT_HORIZON_DAYS = 45;

export type ForecastSource = "baseline" | "clairic";

/** Development only: inject `{ pace, finish, credit, hosted }` for browser checks. */
export const FORECAST_PREVIEW_EVENT = "twyne:forecast-preview";

type Ask = (request: ExtractionRequest) => Promise<ExtractionResult>;

interface ModelOptions {
  /** Absent → baseline only. */
  ask?: Ask;
  store?: ForecastCacheStore;
}

export function clientAsk(client: ConvexClient | null | undefined): Ask | undefined {
  return client ? (request) => askExtraction(client, request) : undefined;
}

const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const weekdayOf = (day: string) => new Date(dayToTime(day)).getDay();

async function stepsFrom(
  ask: Ask,
  request: ExtractionRequest,
): Promise<Interval[]> {
  const result = await ask(request);
  return result.ok ? forecastSteps(result.answers?.next) : [];
}

/* ── Today's pace ─────────────────────────────────────────────── */

export interface PaceForecast extends Interval {
  wordsSoFar: number;
  source: ForecastSource;
}

export function paceHistory(ledger: PaceLedger, today: string): PaceHistoryDay[] {
  const out: PaceHistoryDay[] = [];
  for (let i = HISTORY_DAYS; i >= 1; i--) {
    const key = addDays(today, -i);
    const day = ledger.days[key];
    if (day) out.push({ weekday: weekdayOf(key), hours: day.hours });
  }
  return out;
}

export async function paceForecast(
  ledger: PaceLedger,
  now: number,
  options: ModelOptions = {},
): Promise<PaceForecast | null> {
  const today = localDay(now);
  const wordsSoFar = Math.max(0, dayTotal(ledger.days[today]));
  if (wordsSoFar < PACE_MIN_WORDS_TODAY) return null;
  const date = new Date(now);
  const hourNow = date.getHours() + date.getMinutes() / 60;
  const history = paceHistory(ledger, today);
  const baseline = paceBaseline({
    history,
    weekday: date.getDay(),
    hourNow,
    wordsSoFar,
  });
  if (!baseline) return null;

  const writingDays = history.filter((d) => d.hours.some((n) => n > 0)).length;
  const enough = writingDays >= MODEL_MIN_DAYS;
  let model: Interval | null = null;
  if (enough && options.ask) {
    const ask = options.ask;
    const startHour = date.getHours();
    const cached = await dailyForecast({
      surface: "pace",
      scope: "all",
      day: today,
      now,
      store: options.store,
      ask: () =>
        stepsFrom(ask, {
          state: paceState(ledger, today, startHour),
          reference_date: today,
          fields: {
            next: forecast(
              "Net words this writer will write in each remaining hour of today, from their hourly history.",
              { min: 0, max: 3_000, horizon: 24 - startHour, interval: "hour" },
            ),
          },
        }),
    });
    if (cached?.steps.length) {
      // The steps begin at the hour of the day's one call; drop the past.
      const askedHour = new Date(cached.askedAt).getHours();
      const offset = date.getHours() - askedHour;
      const ahead = cached.steps.slice(Math.max(0, offset));
      if (ahead.length) {
        const left = 1 - date.getMinutes() / 60;
        const rest = sumSteps([
          { ...scale(ahead[0], left) },
          ...ahead.slice(1),
        ]);
        model = {
          median: wordsSoFar + rest.median,
          p10: wordsSoFar + rest.p10,
          p90: wordsSoFar + rest.p90,
        };
      }
    }
  }
  const chosen = preferForecast(baseline, model, enough)!;
  return { ...chosen.value, wordsSoFar, source: chosen.source };
}

const scale = (s: Interval, k: number): Interval => ({
  median: s.median * k,
  p10: s.p10 * k,
  p90: s.p90 * k,
});

function paceState(ledger: PaceLedger, today: string, hour: number): string {
  const lines = ["Net words written per local hour (00–23), recent days:"];
  for (let i = HISTORY_DAYS; i >= 1; i--) {
    const key = addDays(today, -i);
    const day = ledger.days[key];
    if (!day) continue;
    lines.push(`${key} ${WEEKDAYS[weekdayOf(key)]}: ${day.hours.map(Math.round).join(",")}`);
  }
  const todays = ledger.days[today]?.hours.slice(0, hour) ?? [];
  lines.push(
    `Today ${today} ${WEEKDAYS[weekdayOf(today)]}, hours 00–${String(hour - 1).padStart(2, "0")}: ${todays.map(Math.round).join(",")}`,
    `Forecast hours ${String(hour).padStart(2, "0")}–23.`,
  );
  return lines.join("\n");
}

/* ── Draft finish ─────────────────────────────────────────────── */

/**
 * The writer's stated length, if the brief states one in words. Pages and
 * "a chapter" are left alone: turning those into a word count would be
 * inventing a target. A range resolves to its lower end — the draft is
 * long enough once it is inside the range.
 */
export function briefWordTarget(brief: ProjectBrief | null | undefined): number | null {
  if (!brief) return null;
  const text = [
    brief.answers.format,
    brief.answers.constraints,
    ...(brief.probes ?? [])
      .filter((p) => p.relatesTo === "format" || p.relatesTo === "constraints")
      .map((p) => (Array.isArray(p.answer) ? p.answer.join(" ") : String(p.answer ?? ""))),
  ].join(" \n ");
  const number = String.raw`(\d{1,3}(?:[,  ]\d{3})+|\d+(?:\.\d+)?)\s*(k)?`;
  const match = new RegExp(
    String.raw`(?:${number})\s*(?:(?:-|–|—|to)\s*(?:${number})\s*)?(?:words?|wds)\b`,
    "i",
  ).exec(text);
  if (!match) return null;
  const value = (raw: string, k?: string) =>
    Number(raw.replace(/[,  ]/g, "")) * (k ? 1_000 : 1);
  // "3–5k words": the k on the upper end applies to a bare lower one.
  const sharedK = !match[2] && match[4] && Number(match[1]) < 1_000;
  const low = value(match[1], match[2] ?? (sharedK ? "k" : undefined));
  if (!Number.isFinite(low) || low < 100 || low > 500_000) return null;
  return Math.round(low);
}

export interface FinishForecast {
  target: number;
  current: number;
  /** Local day keys. */
  median: string;
  early: string;
  late: string;
  source: ForecastSource;
}

export async function finishForecast(input: {
  ledger: PaceLedger;
  folioId: string;
  currentWords: number;
  target: number | null;
  now: number;
  options?: ModelOptions;
}): Promise<FinishForecast | null> {
  const { target, currentWords } = input;
  if (!target || currentWords >= target) return null;
  const today = localDay(input.now);
  const { gains, observedDays } = folioDailyGains(
    input.ledger,
    input.folioId,
    today,
    HISTORY_DAYS,
  );
  // Today is still being written; judge the pace on finished days.
  const finished = gains.slice(0, -1);
  const remaining = target - currentWords;
  const baseline = daysToReach(finished, remaining);
  if (!baseline || baseline.median > 366) return null;

  const enough = observedDays - 1 >= MODEL_MIN_DAYS;
  let model: Interval | null = null;
  const ask = input.options?.ask;
  if (enough && ask) {
    const cached = await dailyForecast({
      surface: "finish",
      scope: input.folioId,
      day: today,
      now: input.now,
      store: input.options?.store,
      ask: () =>
        stepsFrom(ask, {
          state: [
            "Net words added to one draft per day, oldest first:",
            ...finished.map(
              (n, i) =>
                `${addDays(today, i - finished.length)} ${WEEKDAYS[weekdayOf(addDays(today, i - finished.length))]}: ${Math.round(n)}`,
            ),
            `Draft is ${currentWords} words; target ${target}.`,
          ].join("\n"),
          reference_date: today,
          fields: {
            next: forecast(
              "Net words this writer will add to the draft on each coming day, starting today.",
              { min: 0, max: 10_000, horizon: FINISH_HORIZON_DAYS, interval: "day" },
            ),
          },
        }),
    });
    // Step n covers day n-1 (today is step 1): convert to days from today.
    const crossing = cached?.steps.length
      ? stepsToReach(cached.steps, remaining)
      : null;
    if (crossing)
      model = {
        median: crossing.median - 1,
        p10: crossing.p10 - 1,
        p90: crossing.p90 - 1,
      };
